class Solution:

    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = (len(s), len(t))
        A_subs = ['']
        for i in range(n):
            for j in range(i + 1, n + 1 - 1):
                A_subs.append(s[i:j])
        B_subs = ['']
        for i in range(m):
            for j in range(i + 1, m + 1):
                B_subs.append(t[i:j])
        max_len = 0
        for A in A_subs:
            for B in B_subs:
                P = A + B
                if P == P[::-1]:
                    if len(P) > max_len:
                        max_len = len(P)
        return max_len

from typing import List

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        n = len(squares)
        ys = [s[1] for s in squares]
        ls = [s[2] for s in squares]
        ends = [ys[i] + ls[i] for i in range(n)]

        min_y = min(ys)
        max_y_plus = max(ends)
        total_area = 0.0
        for l in ls:
            total_area += l * l
        half_area = total_area / 2.0

        lo, hi = min_y, max_y_plus
        # Perform binary search to find t such that area below(t) ≈ half_area
        for _ in range(60):
            mid = (lo + hi) / 2.0
            below = 0.0
            for i in range(n):
                yi = ys[i]
                li = ls[i]
                if mid <= yi:
                    continue
                end_i = ends[i]
                if mid >= end_i:
                    below += li * li
                else:
                    below += (mid - yi) * li
            if below < half_area:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2.0
